# Initialize an empty dictionary to group columns by table name
tables = {}

# 1. Loop through all incoming items
for item in _items:
    # Safely handle potential legacy 'json' wrappers
    internal_data = item.get('json', item)

    if not internal_data:
        continue

    # Extract fields from the item
    tablename = internal_data.get('tablename')
    schemaname = internal_data.get('schemaname')
    column_name = internal_data.get('column_name')
    data_type = internal_data.get('data_type')

    # Skip processing if critical fields are missing
    if not tablename or not column_name or not data_type:
        continue

    # If the table isn't tracked yet, initialize it
    if tablename not in tables:
        tables[tablename] = {
            'schema': schemaname or 'public',  # Fallback to public if null
            'columns': []
        }

    # Append the formatted string "column_name (data_type)" to the list
    tables[tablename]['columns'].append(f"{column_name} ({data_type})")

# 2. Build the output text lines
result_lines = []
for tablename, table_info in tables.items():
    schema = table_info['schema']
    columns_str = ", ".join(table_info['columns'])

    line = f"Table {tablename} (Schema: {schema}) has columns: {columns_str}"
    result_lines.append(line)

# Join the blocks with double newlines exactly like the JS version
transformed_schema = "\n\n".join(result_lines)

# 3. Return the string wrapped inside n8n's expected list structure
return [
    {
        "json": {
            "data": transformed_schema
        }
    }
]
